-- V5 : 출처 VIEW 정의·정의 확인 이력 (DEC-16 원본 VIEW 정의 수집, 2026-11-16 — docs/completed/source-view-definition-dec16.md).
-- 정의 원문은 이 테이블에만 둔다 (카탈로그 버전·이력에는 해시만). 기존 원본 카탈로그 데이터는 바꾸지 않는다 : 정의는 다음 수집부터 채워진다.
-- 예제(프로젝트 0)에 두 테이블을 용어 → 물리 → 논리 → 매핑 → 관계 → 인덱스 → 업무 설명 순서로 넣는다 (V3·V4 와 같은 규칙).
create sequence SQ_SRC_VIEW_DFN start with 1 increment by 50;
create table TB_SRC_VIEW_DFN (
    SRC_VIEW_DFN_SN bigint not null,
    PRJ_SN bigint not null,
    SRC_CNTN_SN bigint not null,
    SRC_TBL_SN bigint not null,
    DFN_STTS_CD varchar(20) not null,
    DFN_CN TEXT,
    ENCPT_YN boolean not null,
    HASH_VL varchar(255),
    BFR_HASH_VL varchar(255),
    DFN_LEN integer,
    CLCT_DT timestamp(6),
    CHG_RFLT_ORD integer,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SRC_VIEW_DFN primary key (SRC_VIEW_DFN_SN)
);
create unique index UX_SRC_VIEW_DFN_01 on TB_SRC_VIEW_DFN (SRC_TBL_SN);
create index IX_SRC_VIEW_DFN_01 on TB_SRC_VIEW_DFN (PRJ_SN);
create index IX_SRC_VIEW_DFN_02 on TB_SRC_VIEW_DFN (SRC_CNTN_SN);
alter table TB_SRC_VIEW_DFN add constraint FK_SRC_VIEW_DFN_01 foreign key (SRC_TBL_SN) references TB_SRC_TBL on delete cascade;
comment on table TB_SRC_VIEW_DFN is '출처 뷰 정의';
comment on column TB_SRC_VIEW_DFN.SRC_VIEW_DFN_SN is '출처 뷰 정의 일련번호';
comment on column TB_SRC_VIEW_DFN.PRJ_SN is '프로젝트 일련번호';
comment on column TB_SRC_VIEW_DFN.SRC_CNTN_SN is '출처 접속 일련번호';
comment on column TB_SRC_VIEW_DFN.SRC_TBL_SN is '출처 테이블 일련번호';
comment on column TB_SRC_VIEW_DFN.DFN_STTS_CD is '정의 상태 코드';
comment on column TB_SRC_VIEW_DFN.DFN_CN is '정의 내용';
comment on column TB_SRC_VIEW_DFN.ENCPT_YN is '암호화 여부';
comment on column TB_SRC_VIEW_DFN.HASH_VL is '해시 값';
comment on column TB_SRC_VIEW_DFN.BFR_HASH_VL is '이전 해시 값';
comment on column TB_SRC_VIEW_DFN.DFN_LEN is '정의 길이';
comment on column TB_SRC_VIEW_DFN.CLCT_DT is '수집 일시';
comment on column TB_SRC_VIEW_DFN.CHG_RFLT_ORD is '변경 반영 순서';
comment on column TB_SRC_VIEW_DFN.REG_DT is '등록 일시';
comment on column TB_SRC_VIEW_DFN.MDFCN_DT is '수정 일시';
comment on column TB_SRC_VIEW_DFN.RGTR_ID is '등록자 아이디';
comment on column TB_SRC_VIEW_DFN.MDFR_ID is '수정자 아이디';
create sequence SQ_SRC_VIEW_DFN_IDNTY_HSTRY start with 1 increment by 50;
create table TB_SRC_VIEW_DFN_IDNTY_HSTRY (
    SRC_VIEW_DFN_IDNTY_HSTRY_SN bigint not null,
    PRJ_SN bigint not null,
    SRC_CNTN_SN bigint not null,
    SRC_TBL_SN bigint not null,
    HASH_VL varchar(255),
    IDNTY_DT timestamp(6) not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_SRC_VIEW_DFN_IDNTY_HSTRY primary key (SRC_VIEW_DFN_IDNTY_HSTRY_SN)
);
create index IX_SRC_VIEW_DFN_IDNTY_HSTRY_01 on TB_SRC_VIEW_DFN_IDNTY_HSTRY (SRC_TBL_SN);
create index IX_SRC_VIEW_DFN_IDNTY_HSTRY_02 on TB_SRC_VIEW_DFN_IDNTY_HSTRY (PRJ_SN);
comment on table TB_SRC_VIEW_DFN_IDNTY_HSTRY is '출처 뷰 정의 확인 이력';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.SRC_VIEW_DFN_IDNTY_HSTRY_SN is '출처 뷰 정의 확인 이력 일련번호';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.PRJ_SN is '프로젝트 일련번호';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.SRC_CNTN_SN is '출처 접속 일련번호';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.SRC_TBL_SN is '출처 테이블 일련번호';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.HASH_VL is '해시 값';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.IDNTY_DT is '확인 일시';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.REG_DT is '등록 일시';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.MDFCN_DT is '수정 일시';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.RGTR_ID is '등록자 아이디';
comment on column TB_SRC_VIEW_DFN_IDNTY_HSTRY.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 용어, 단어는 모두 있다) ----------
-- ---------- 예제 : 물리 모델 TB_SRC_VIEW_DFN ----------
-- ---------- 예제 : 논리 모델 출처 뷰 정의 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 출처 뷰 정의 ----------
-- ---------- 예제 : 관계 TB_SRC_VIEW_DFN (V5 의 FK 그대로, 삭제 규칙 포함) ----------
update TB_TBL_REL set DEL_RULE_CD = 'CASCADE' where PRJ_SN = 0 and upper(REL_NM) = 'FK_SRC_VIEW_DFN_01' and REL_TYPE_CD = 'FK' and DEL_RULE_CD is null;
-- ---------- 예제 : 인덱스 TB_SRC_VIEW_DFN (V5 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 TB_SRC_VIEW_DFN ----------
update TB_TBL set TASK_EXPLN = '출처 DB 에서 읽은 VIEW 정의 원문을 보관한 기록. 업무 규칙·리터럴이 들어 있을 수 있어 권한 있는 사용자만 보고, 볼 때마다 확인 이력이 남는다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '뷰 정의 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'SRC_VIEW_DFN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의가 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의를 읽은 출처 접속.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'SRC_CNTN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의의 출처 VIEW. VIEW 행을 지우면 함께 지워진다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'SRC_TBL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '마지막 수집에서 정의를 읽은 결과 : 수집됨·권한 없음·실패·너무 큼.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'DFN_STTS_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '마지막으로 읽은 정의 원문 (키가 있으면 암호화). 읽지 못한 수집에서는 바꾸지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'DFN_CN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의 원문을 암호화해 저장했는지 여부.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'ENCPT_YN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의 원문의 해시. 수집 사이의 정의 변경을 원문 없이 비교한다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'HASH_VL' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의가 바뀌기 전의 해시. 비어 있으면 처음 수집한 정의다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'BFR_HASH_VL' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의 원문의 글자 수.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'DFN_LEN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의 원문을 마지막으로 읽은 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'CLCT_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의가 처음 수집되었거나 마지막으로 바뀐 수집의 반영 순서.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'CHG_RFLT_ORD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
