update TB_TBL set TASK_EXPLN = '권한 있는 사용자가 출처 VIEW 정의 원문을 확인한 기록. 원문은 남기지 않고 그때의 해시만 남긴다.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인 이력 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'SRC_VIEW_DFN_IDNTY_HSTRY_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이력이 속한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인한 정의의 출처 접속.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'SRC_CNTN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인한 출처 VIEW (번호로만 남는다).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'SRC_TBL_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '확인할 때의 정의 해시 (원문은 남기지 않는다).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'HASH_VL' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '정의 원문을 확인한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'IDNTY_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_SRC_VIEW_DFN_IDNTY_HSTRY' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
